INSERT INTO public.qc_parameters (source, category, parameter, description) VALUES
('phone_call', 'Authenticity', 'Minimum viable turn count', 'Transcript has fewer than 6 distinct speech turns for its duration — looks like a monologue or a call that never really started.'),
('phone_call', 'Authenticity', 'Turns-per-minute sanity', 'Number of back-and-forth turns per minute of call duration is implausibly low (near-silence / one-sided).'),
('phone_call', 'Authenticity', 'Words-per-minute sanity (too fast)', 'Transcript word count implies >210 spoken words/minute sustained — suggests transcript/audio mismatch or spliced content.'),
('phone_call', 'Authenticity', 'Words-per-minute sanity (too slow)', 'Transcript word count implies <45 spoken words/minute — suggests long dead air, hold music, or a mis-fetched recording rather than live counselling.'),
('phone_call', 'Authenticity', 'Prospect responsiveness present', 'Lead''s turns include natural short acknowledgements/answers (yes/no/okay/numbers) — evidence of a real two-sided conversation, not a read monologue.'),
('phone_call', 'Authenticity', 'Prospect asks at least one question', 'A genuine, engaged prospect usually asks something back (about fees, colleges, placements, process) — total absence across a long call is a mild red flag.'),
('phone_call', 'Authenticity', 'Lead name used correctly & consistently', 'Lead''s own name is referenced in the transcript and stays consistent (no other, different lead name appearing) — a mismatch suggests the wrong recording/notes were logged.'),
('phone_call', 'Authenticity', 'Personal/discovery detail specific to this lead', 'Call contains at least one lead-specific fact (board %, JEE score, city, school) rather than being 100% generic script text — generic-only calls are harder to verify as genuinely tailored.'),
('phone_call', 'Authenticity', 'Duration vs. content-depth match', 'Call duration is broadly consistent with the depth of topics actually covered (e.g. a 20-minute call covering almost nothing, or a 2-minute call marked as covering the full script).'),
('phone_call', 'Authenticity', 'No abrupt mid-sentence cutoff', 'Transcript doesn''t end mid-word/mid-sentence in a way suggesting the recording was cut/edited.'),
('phone_call', 'Authenticity', 'Single-speaker dominance ratio', 'Share of total transcript characters contained in long (>200 char) uninterrupted lines is within a normal counselling range, not near-100% monologue.'),
('phone_call', 'Authenticity', 'No verbatim block reused across different leads by same associate', 'Long (~40+ word) verbatim passages are expected script lines, but if an entire transcript is near-identical to another call by the same associate with a different lead, flag for manual copy-paste/fabrication check.'),
('phone_call', 'Authenticity', 'Student count claim within canonical range', 'Stated total enrolled-student figure is close to Kalvium''s standard figure (~2,200) rather than an outlier (e.g. 5,000+) that suggests improvisation/exaggeration. NOTE: this regex also catches a partner university''s OWN enrolment stats quoted for context (e.g. ''LPU had 5,000 students in CSC'') -- treat a fail here as ''verify by listening'', not a confirmed violation.'),
('phone_call', 'Authenticity', 'University count claim within canonical range', 'Stated partner-university count is close to the standard figure (~10-12) rather than a wildly different number.'),
('phone_call', 'Authenticity', 'No fabricated urgency/scarcity claims', 'No invented scarcity pressure such as ''only X seats left today'' / ''offer expires tonight'' that isn''t part of the approved script.'),
('phone_call', 'Authenticity', 'No invented placement/salary statistics outside script norms', 'Any LPA/salary figures quoted fall within the ranges normally used in the script rather than an inflated one-off number.'),
('phone_call', 'Authenticity', 'Call not simply a voicemail/no-answer', 'Transcript reflects an actual conversation and is not just ringing tones, a voicemail message, or ''call not connected'' content mislabeled as a completed counselling call.'),
('phone_call', 'Authenticity', 'transcription_status corroborates a full call', 'Backend transcription_status is ''success'' and transcript_length is non-trivial relative to duration.'),
('phone_call', 'Authenticity', 'audio_fetch_status corroborates a real recording', 'Backend audio_fetch_status is ''success'', i.e. an actual audio file exists behind this log entry.'),
('phone_call', 'Authenticity', 'No signs of a scripted ''demo'' recording', 'No meta-references such as ''this is a sample call'' / ''for training purposes'' / associate coaching another associate rather than speaking to a prospect.'),
('phone_call', 'Authenticity', 'Notes/summary internally consistent with transcript length', 'The auditor notes/summary do not claim full script coverage while the underlying transcript is extremely short (or vice versa) — inconsistency suggests the summary wasn''t genuinely derived from this call.'),
('phone_call', 'Compliance', 'Associate identity captured', 'associate_name field is populated and non-generic.'),
('phone_call', 'Compliance', 'Lead identity captured', 'lead_name field is populated and non-generic.'),
('phone_call', 'Compliance', 'Prospect ID present & well-formed', 'prospect_id exists and is a valid unique identifier (no blank/placeholder).'),
('phone_call', 'Compliance', 'Recording link reachable', 'audio_recording_url is present and correctly formed (not blank/broken).'),
('phone_call', 'Compliance', 'Call duration logged and plausible', 'call_duration_seconds is present and within a plausible range for a counselling call (not 0 or absurdly small/large).'),
('phone_call', 'Compliance', 'Only one recording per prospect record', 'This prospect_id is not sharing its audio file with any other prospect_id in the same audit batch.'),
('phone_call', 'Compliance', 'Notes field is call-specific, not boilerplate', 'notes / script_coverage_summary text reads as specific to this call rather than an identical stock sentence reused everywhere.'),
('phone_call', 'Compliance', 'Consistent associate attribution', 'Same associate name spelling/casing used consistently for this associate elsewhere in the batch (flags likely data-entry/identity issues, not the associate''s fault, but worth cleaning).'),
('phone_call', 'Compliance', 'No missing/blank critical fields', 'None of the required fields (associate, lead, duration, transcript) are empty for this row.'),
('phone_call', 'Compliance', 'Transcript language field present where relevant', 'native_transcript populated when the call included non-English speech (supports verification against english_transcript).'),
('phone_call', 'Introduction', 'Self introduction (name)', 'Associate states their own name.'),
('phone_call', 'Introduction', 'Company introduction (Kalvium)', 'Associate names Kalvium as the organisation calling.'),
('phone_call', 'Introduction', 'Reason for call stated', 'Associate explains why they are calling (follow-up on an enquiry/form).'),
('phone_call', 'Introduction', 'Confirms speaking to the right person', 'Associate verifies they are speaking to the actual lead (not a parent/sibling) before pitching.'),
('phone_call', 'Introduction', 'Confirms prior interest/lead source', 'Associate references the specific form/enquiry the lead had submitted.'),
('phone_call', 'Introduction', 'Asks permission / checks availability', 'Associate asks if it''s a good time / requests a few minutes before diving in.'),
('phone_call', 'Introduction', 'Warm, non-robotic opening tone', 'Opening lines vary/feel conversational rather than a rigid word-for-word script read (proxy: presence of natural filler/acknowledgement words).'),
('phone_call', 'Introduction', 'Sets call agenda', 'Associate briefly previews what the call will cover.'),
('phone_call', 'Introduction', 'Introduction not skipped entirely', 'Some introduction element is present at all (baseline floor, distinct from quality of intro).'),
('phone_call', 'Introduction', 'Appropriate greeting used', 'A greeting (hello/good morning/good evening) opens the call.'),
('phone_call', 'Discovery', 'Class 12 / academic status checked', 'Associate asks about Class 12 completion status.'),
('phone_call', 'Discovery', 'Board exam result / percentage discussed', 'Board marks or percentage are discussed.'),
('phone_call', 'Discovery', 'Entrance exam (JEE/other) status discussed', 'JEE or equivalent entrance exam attempt/score is discussed where relevant.'),
('phone_call', 'Discovery', 'Stream / subject interest confirmed', 'Associate confirms interest in CSE/engineering or the relevant stream.'),
('phone_call', 'Discovery', 'Career goal / motivation explored', 'Associate asks about the lead''s career goals or reasons for interest.'),
('phone_call', 'Discovery', 'Parents'' involvement discussed', 'Associate checks whether parents are part of the decision and includes them appropriately.'),
('phone_call', 'Discovery', 'Current alternatives/competing options discussed', 'Associate asks what other colleges/programs the lead is considering.'),
('phone_call', 'Discovery', 'Decision timeline discussed', 'Associate asks when the lead plans to decide/enrol.'),
('phone_call', 'Discovery', 'Location / relocation preference discussed', 'Associate discusses willingness to relocate or preferred city/region.'),
('phone_call', 'Discovery', 'Budget/affordability sensitively explored', 'Fee range or affordability is discussed without being the sole focus.'),
('phone_call', 'Discovery', 'Discovery questions open-ended, not just yes/no', 'At least some discovery questions invite more than a one-word answer (proxy via lead response length).'),
('phone_call', 'Discovery', 'Discovery not entirely skipped', 'Some discovery/qualification element occurs at all (baseline floor).'),
('phone_call', 'ProgramPitch', 'B.Tech CSE / Work-Integrated Program explained', 'The core Work-Integrated B.Tech CSE program is explained.'),
('phone_call', 'ProgramPitch', 'Program structure/duration explained', 'How the program runs (years, structure) is described.'),
('phone_call', 'ProgramPitch', 'Partner-university model explained', 'Associate explains the multi-university delivery model correctly (curriculum consistent across partner campuses).'),
('phone_call', 'ProgramPitch', 'At least one real partner university named', 'A recognisable, real partner university (e.g. LPU, SRM, JECRC, VIT, Amity) is mentioned by name.'),
('phone_call', 'ProgramPitch', 'University count claim present', 'A specific partner-university count is stated (supports E-15/A-15 fact-check).'),
('phone_call', 'ProgramPitch', 'Student enrolment figure cited', 'A specific enrolled/alumni student count is cited (supports A-14 fact-check).'),
('phone_call', 'ProgramPitch', 'Day-one coding / practical curriculum emphasised', 'Associate emphasises hands-on coding/project work starting early.'),
('phone_call', 'ProgramPitch', 'Industry relevance / AI-era relevance explained', 'Associate connects the program to current industry/AI-era hiring relevance.'),
('phone_call', 'ProgramPitch', 'Coding/projects specifics mentioned', 'Concrete detail on coding exposure or project-based learning is given (not just a buzzword).'),
('phone_call', 'ProgramPitch', 'Faculty/mentorship model mentioned', 'Who teaches / mentors students is mentioned.'),
('phone_call', 'ProgramPitch', 'Fee structure mentioned or offered to be shared', 'Fees, payment plans, or scholarships are discussed or explicitly deferred to a documented next step.'),
('phone_call', 'ProgramPitch', 'No unauthorised placement guarantee', 'Associate does not promise guaranteed placement (should mirror the compliant disclaimer pattern: ''we don''t guarantee, but train you'').'),
('phone_call', 'ProgramPitch', 'Salary/package figures, if given, framed as illustrative not guaranteed', 'Any LPA figures quoted are framed as examples/ranges rather than promises.'),
('phone_call', 'ProgramPitch', 'Accreditation / recognition addressed', 'Associate addresses degree validity/recognition when relevant/asked.'),
('phone_call', 'ProgramPitch', 'Internship component explained', 'Internship opportunities are explained accurately (paid/unpaid status not overstated).'),
('phone_call', 'ProgramPitch', 'No overstated exclusivity (''only program of its kind'') beyond script', 'Claims of uniqueness are consistent with the standard differentiation pitch (see category F) rather than invented superlatives.'),
('phone_call', 'ProgramPitch', 'Program pitch not entirely skipped', 'Some program-pitch element occurs at all (baseline floor).'),
('phone_call', 'ProgramPitch', 'Pitch tailored to stated interest (not generic-only)', 'Program explanation references the lead''s own stated stream/goal rather than being a fully generic block.'),
('phone_call', 'Differentiation', 'Comparison vs. traditional college route made', 'Associate explains how this differs from a typical B.Tech/college experience.'),
('phone_call', 'Differentiation', 'Curriculum-over-campus positioning explained', 'Associate explains that value comes from the curriculum/program, not the specific campus/college name.'),
('phone_call', 'Differentiation', 'Skill/employability focus articulated', 'Differentiation is framed around skills and job-readiness, not just brand/ranking claims.'),
('phone_call', 'Differentiation', 'No disparagement of specific named competitor colleges', 'Comparisons are made without unfairly disparaging a specific competitor institution.'),
('phone_call', 'Differentiation', 'Consistent with company-approved comparison points', 'Differentiation claims align with the recurring standard talking points seen across the wider call sample (proxy: overlap with common phrasing set).'),
('phone_call', 'Differentiation', 'Addresses ''why not IIT/top exam college'' objection where relevant', 'When the lead references a top exam/college ambition, the associate responds to it rather than ignoring it.'),
('phone_call', 'Differentiation', 'Explains the AI-era/future relevance angle', 'Differentiation includes why this preparation matters for an AI-changed job market.'),
('phone_call', 'Differentiation', 'No fabricated exclusivity claims (''first and only in India'')', 'Superlative claims, if made, are not contradicted elsewhere in the wider dataset''s standard script.'),
('phone_call', 'Differentiation', 'Differentiation segment not entirely skipped', 'Some differentiation content occurs at all (baseline floor).'),
('phone_call', 'Differentiation', 'Balanced tone (confident, not disparaging or exaggerated)', 'Overall tone of the differentiation pitch is confident and factual rather than aggressive or over-the-top.'),
('phone_call', 'Objections', 'Cost/fee objection addressed if raised', 'If the lead raises a cost concern, the associate responds to it directly.'),
('phone_call', 'Objections', 'Parental approval objection addressed if raised', 'If the lead mentions needing to check with parents, associate responds constructively (not pressuring).'),
('phone_call', 'Objections', '''Not a well-known college'' objection addressed if raised', 'If brand/recognition concerns are raised, associate responds with the curriculum/outcomes framing.'),
('phone_call', 'Objections', '''Will I get a job'' objection addressed if raised', 'If job-security concerns are raised, associate responds without over-promising.'),
('phone_call', 'Objections', 'No pressure tactics used in response to hesitation', 'Associate does not use guilt, false urgency, or repeated pushing after a clear ''no''/hesitation.'),
('phone_call', 'Objections', 'Associate acknowledges the objection before responding', 'Response pattern shows acknowledgement (''I understand'', ''that''s a fair question'') rather than talking over the objection.'),
('phone_call', 'Objections', 'Objection responses are specific, not deflected generically', 'Responses address the actual concern raised rather than pivoting to an unrelated script line.'),
('phone_call', 'Objections', 'Lead''s hesitation/questions are not cut off', 'Long associate turns don''t immediately follow a lead question without an intervening answer.'),
('phone_call', 'Objections', 'No use of comparative fear (e.g. ''you''ll be left behind'') beyond script norm', 'Persuasion avoids manufactured fear-based pressure beyond the standard AI-relevance framing.'),
('phone_call', 'Objections', 'Objection handling present when objections exist', 'Where the transcript shows a lead objection/hesitation cue, some associate response follows (not silence/topic change).'),
('phone_call', 'Closure', 'Call summarised before ending', 'Associate briefly recaps what was discussed/agreed.'),
('phone_call', 'Closure', 'Clear next step defined', 'A concrete next step (webinar date, registration, follow-up call) is agreed.'),
('phone_call', 'Closure', 'Registration/close attempted', 'Associate attempts to move the lead toward registration/enrollment interest, per ''Registration/close'' scripting.'),
('phone_call', 'Closure', 'Thanks / polite sign-off', 'Call ends with a courteous thank-you/goodbye.'),
('phone_call', 'Closure', 'Follow-up timing set if not closed', 'If the lead doesn''t commit, a specific follow-up time/date is set rather than leaving it open-ended.'),
('phone_call', 'Closure', 'No abrupt/unexplained call termination', 'Call does not end mid-topic without any closing exchange.'),
('phone_call', 'Closure', 'Lead''s final sentiment captured', 'Transcript shows the lead''s own closing response (agree/maybe/decline), not just the associate talking.'),
('phone_call', 'Closure', 'Closure segment not entirely skipped', 'Some closure content occurs at all (baseline floor).'),
('phone_call', 'Closure', 'Consistent with stated Closure field', 'This category''s automated read is broadly consistent with the pre-existing ''Closure'' column value for this call.'),
('phone_call', 'Closure', 'No contradictory promises made at closing', 'Nothing promised at closing (dates, guarantees) contradicts what was said earlier in the call.'),
('phone_call', 'SoftSkills', 'Active listening signals present', 'Associate paraphrases/references what the lead just said (proxy: echoing lead''s own words back).'),
('phone_call', 'SoftSkills', 'Avoids talking over the lead', 'Long associate monologues are not immediately followed by cutting off a lead''s short reply (proxy via turn-length pattern).'),
('phone_call', 'SoftSkills', 'Patience with repeated/basic questions', 'If the lead repeats a question, associate re-explains patiently rather than showing irritation (proxy: no curt one-word repeats).'),
('phone_call', 'SoftSkills', 'Empathetic language used', 'Phrases showing empathy/reassurance appear (''I understand'', ''no worries'', ''that''s a valid concern'').'),
('phone_call', 'SoftSkills', 'Professional language throughout', 'No unprofessional language, slang, or inappropriate remarks detected.'),
('phone_call', 'SoftSkills', 'Appropriate pacing (not rushed)', 'Speaking pace (WPM) sits in a natural conversational range rather than rushed.'),
('phone_call', 'SoftSkills', 'Clarity — avoids excessive filler/repetition', 'Associate turns aren''t dominated by excessive verbal filler or needless repetition (proxy: repeated-word ratio).'),
('phone_call', 'SoftSkills', 'Handles language-switching smoothly', 'Where native-language segments appear, the associate transitions between English/native language without confusion (checked against native_transcript availability).'),
('phone_call', 'SoftSkills', 'Confidence in delivery', 'Program facts are delivered without excessive hedging/uncertainty (''I think'', ''maybe'', ''not sure'') on core facts.'),
('phone_call', 'SoftSkills', 'Enthusiasm/energy conveyed', 'Positive, energetic framing is used when describing the program (proxy: positive-language density).'),
('phone_call', 'SoftSkills', 'Lead''s engagement sustained to the end', 'Lead continues responding through to the later portion of the call, not just the opening (evidence call didn''t lose the prospect).'),
('phone_call', 'SoftSkills', 'No dead-air heavy sections', 'No unusually long single lines suggesting extended unscripted silence/hold within an otherwise short call.'),
('phone_call', 'EthicalRisk', 'No false placement guarantee', 'No unqualified ''100% placement guaranteed'' style claim (see E12/G-pattern) that oversteps the approved disclaimer.'),
('phone_call', 'EthicalRisk', 'No false accreditation/recognition claim', 'No inaccurate claim about degree recognition/accreditation status.'),
('phone_call', 'EthicalRisk', 'No fabricated scarcity/urgency (''only today'', ''last seat'')', 'No manufactured urgency beyond genuine deadlines.'),
('phone_call', 'EthicalRisk', 'No discriminatory or inappropriate remarks', 'No remarks about gender, caste, religion, or similar that would be inappropriate.'),
('phone_call', 'EthicalRisk', 'No misuse of personal data mentioned', 'No indication personal data is being shared/used outside the counselling purpose.'),
('phone_call', 'EthicalRisk', 'No pressure to decide immediately on payment', 'Associate does not push for immediate payment/commitment on the call itself.'),
('phone_call', 'EthicalRisk', 'No disparagement of the lead''s current school/college', 'Associate does not belittle the lead''s current or prior institution.'),
('phone_call', 'EthicalRisk', 'No inconsistent/contradictory factual claims within the same call', 'Numbers or claims don''t contradict themselves within the same transcript. NOTE: the script legitimately cites multiple different figures in one call (this-year vs last-year cohort size, or a named partner university''s own stats) -- a fail here means ''multiple numbers detected, worth a quick listen'', not a confirmed contradiction.'),
('phone_call', 'EthicalRisk', 'No inappropriate personal questions', 'No questions unrelated to admissions counselling (financial status beyond fees, personal life probing).'),
('phone_call', 'EthicalRisk', 'Recording/consent context not contradicted', 'Nothing in the transcript suggests the lead was unaware they were speaking with a counsellor (e.g. impersonation of another role).'),
('google_meet', 'DemoSetup', 'Screen shared promptly', 'Presenter shares their screen within the first 2 minutes of the meeting.'),
('google_meet', 'DemoSetup', 'Audio and video quality acceptable', 'No significant audio or video issues that impaired the demo experience (echo, lag, muting problems).'),
('google_meet', 'DemoSetup', 'Agenda set at the start', 'Presenter briefly previews what the demo will cover before diving in.'),
('google_meet', 'DemoSetup', 'Attendees acknowledged', 'Presenter acknowledges attendees by name and confirms who is on the call.'),
('google_meet', 'DemoSetup', 'Platform/tool introduced', 'Presenter names the product/platform being demonstrated.'),
('google_meet', 'ProductWalkthrough', 'Core product explained clearly', 'The main product offering is explained in a way a first-time viewer would understand.'),
('google_meet', 'ProductWalkthrough', 'Key features demonstrated', 'At least the core features of the product are shown with live examples.'),
('google_meet', 'ProductWalkthrough', 'Navigation was logical', 'The demo follows a logical flow rather than jumping between unrelated sections.'),
('google_meet', 'ProductWalkthrough', 'Real examples used', 'Presenter uses real or realistic data/examples rather than placeholder/dummy content.'),
('google_meet', 'ProductWalkthrough', 'Pace was appropriate', 'Demo moves at a pace the audience can follow — not too fast or too slow.'),
('google_meet', 'Engagement', 'Questions encouraged during demo', 'Presenter pauses to ask if attendees have questions, rather than only at the end.'),
('google_meet', 'Engagement', 'Attendee questions answered', 'When attendees ask questions they are answered directly and not deflected.'),
('google_meet', 'Engagement', 'Interactive elements used', 'Presenter invites attendees to participate (e.g., ''what would you like to see next?'').'),
('google_meet', 'Engagement', 'Audience attention maintained', 'No long monologues without checking in with attendees.'),
('google_meet', 'Engagement', 'Enthusiasm and energy conveyed', 'Presenter shows genuine enthusiasm about the product rather than a flat monotone delivery.'),
('google_meet', 'TechnicalAccuracy', 'Features described accurately', 'No incorrect claims about what the product can or cannot do.'),
('google_meet', 'TechnicalAccuracy', 'No technical errors during demo', 'Demo runs without crashes, errors, or broken features that undermine credibility.'),
('google_meet', 'TechnicalAccuracy', 'Data shown is accurate', 'Numbers and data shown on screen are realistic and accurate.'),
('google_meet', 'TechnicalAccuracy', 'Limitations acknowledged honestly', 'When asked about missing features, presenter is honest rather than making false promises.'),
('google_meet', 'Objections', 'Pricing questions handled if raised', 'If pricing comes up, it is addressed clearly or deferred to a documented next step.'),
('google_meet', 'Objections', 'Comparison questions handled', 'If attendees compare to competitors, presenter responds confidently without disparagement.'),
('google_meet', 'Objections', 'Hesitation acknowledged', 'Presenter acknowledges concerns rather than talking over them.'),
('google_meet', 'Objections', 'No pressure tactics used', 'Presenter does not use guilt or false urgency to push for a decision.'),
('google_meet', 'Closure', 'Demo summarised before ending', 'Presenter briefly recaps what was shown and key takeaways.'),
('google_meet', 'Closure', 'Clear next step defined', 'A concrete next step is proposed (trial signup, follow-up call, send materials).'),
('google_meet', 'Closure', 'Follow-up timing set', 'A specific date/time for follow-up is agreed rather than leaving it open-ended.'),
('google_meet', 'Closure', 'Thanks and polite sign-off', 'Demo ends with a courteous thank-you and goodbye.'),
('google_meet', 'Closure', 'Recording or materials offered', 'Presenter offers to share the recording or supplementary materials.'),
('google_meet', 'SoftSkills', 'Professional language throughout', 'No unprofessional language or inappropriate remarks.'),
('google_meet', 'SoftSkills', 'Active listening signals present', 'Presenter paraphrases or references what attendees said.'),
('google_meet', 'SoftSkills', 'Patience with repeated questions', 'If an attendee repeats a question, presenter re-explains patiently.'),
('google_meet', 'SoftSkills', 'Clear and confident delivery', 'Presenter speaks clearly without excessive filler words or uncertainty on core facts.'),
('google_meet', 'SoftSkills', 'Smooth screen transitions', 'Presenter navigates between screens and tabs smoothly without confusion.');
